class Solution { private lateinit var grid:Array<String>;private var rows=0;private var cols=0;private var food=0;private var catJump=0;private var mouseJump=0;private var cells=0;private lateinit var memo:ByteArray;private fun dfs(turn:Int,mouse:Int,cat:Int):Boolean{if(cat==mouse||cat==food||turn>=1000)return false;if(mouse==food)return true;val key=(turn*cells+mouse)*cells+cat;if(memo[key].toInt()!=0)return memo[key].toInt()==1;val mouseTurn=turn%2==0;val position=if(mouseTurn)mouse else cat;val jump=if(mouseTurn)mouseJump else catJump;val row=position/cols;val col=position%cols;val directions=arrayOf(intArrayOf(0,0),intArrayOf(1,0),intArrayOf(-1,0),intArrayOf(0,1),intArrayOf(0,-1));var result=!mouseTurn;loop@for(direction in directions){val limit=if(direction[0]==0&&direction[1]==0)0 else jump;for(step in 0..limit){val nextRow=row+direction[0]*step;val nextCol=col+direction[1]*step;if(nextRow !in 0 until rows||nextCol !in 0 until cols||grid[nextRow][nextCol]=='#')break;val next=nextRow*cols+nextCol;val child=if(mouseTurn)dfs(turn+1,next,cat) else dfs(turn+1,mouse,next);if(mouseTurn&&child){result=true;break@loop};if(!mouseTurn&&!child){result=false;break@loop}}};memo[key]=if(result)1 else 2;return result};fun canMouseWin(grid:Array<String>,catJump:Int,mouseJump:Int):Boolean{this.grid=grid;this.catJump=catJump;this.mouseJump=mouseJump;rows=grid.size;cols=grid[0].length;cells=rows*cols;var mouse=0;var cat=0;for(row in 0 until rows)for(col in 0 until cols)when(grid[row][col]){'M'->mouse=row*cols+col;'C'->cat=row*cols+col;'F'->food=row*cols+col};memo=ByteArray(1000*cells*cells);return dfs(0,mouse,cat)} }
